typedef struct { char c; uint8_t attr; } char_cell_t;
static char_cell_t terminal_buffer[ROWS][COLS];
static int cursor_x = 0, cursor_y = 0;
static struct limine_framebuffer* global_fb = NULL;
static uint32_t vga_colors[] = { 0x000000, 0x0000AA, 0x00AA00, 0x00AAAA, 0xAA0000, 0xAA00AA, 0xAA5500, 0xAAAAAA,
    0x555555, 0x5555FF, 0x55FF55, 0x55FFFF, 0xFF5555, 0xFF55FF, 0xFFFF55, 0xFFFFFF };

void draw_char_at(char c, int x, int y, uint8_t attr) {
    if (!global_fb || (uint8_t)c >= 128 || x < 0 || x >= COLS || y < 0 || y > ROWS) return;
    if ((y + 1) * 8 * SCALE > (int)global_fb->height) return;
    uint32_t fg = vga_colors[attr & 0x0F], bg = vga_colors[attr >> 4];
    const uint8_t* glyph = font8x8_basic[(uint8_t)c];
    for (int i=0; i<8; i++) {
        for (int j=0; j<8; j++) {
            uint32_t color = (glyph[i] & (1 << (7 - j))) ? fg : bg;
            for (int sy=0; sy<SCALE; sy++) {
                for (int sx=0; sx<SCALE; sx++) {
                    int py = y*8*SCALE + i*SCALE + sy, px = x*8*SCALE + j*SCALE + sx;
                    if (px >= 0 && (uint64_t)px < global_fb->width && py >= 0 && (uint64_t)py < global_fb->height) {
                        ((uint32_t*)global_fb->address)[(py*global_fb->pitch/4) + px] = color;
                    }
                }
            }
        }
    }
}

void vga_clear(void) {
    if (!global_fb) return;
    for (uint64_t i=0; i<global_fb->height * global_fb->pitch / 4; i++) ((uint32_t*)global_fb->address)[i] = 0;
    for (int y=0; y<ROWS; y++) for (int x=0; x<COLS; x++) { terminal_buffer[y][x].c = ' '; terminal_buffer[y][x].attr = 0x07; }
    cursor_x = cursor_y = 0;
}

void vga_write_char(char c, uint8_t attr) {
    if (c == '\b') {
        serial_write_str("\b \b"); if (cursor_x > 0) cursor_x--;
        terminal_buffer[cursor_y][cursor_x].c = ' '; draw_char_at(' ', cursor_x, cursor_y, attr);
        return;
    }
    serial_write_char(c);
    if (c == '\n') { cursor_x = 0; cursor_y++; }
    else {
        terminal_buffer[cursor_y][cursor_x] = (char_cell_t){c, attr};
        draw_char_at(c, cursor_x, cursor_y, attr);
        cursor_x++; if (cursor_x >= COLS) { cursor_x = 0; cursor_y++; }
    }
    if (cursor_y >= ROWS) {
        for (int y=0; y<ROWS-1; y++) {
            for (int x=0; x<COLS; x++) {
                terminal_buffer[y][x] = terminal_buffer[y+1][x];
                draw_char_at(terminal_buffer[y][x].c, x, y, terminal_buffer[y][x].attr);
            }
        }
        for (int x=0; x<COLS; x++) { terminal_buffer[ROWS-1][x].c = ' '; terminal_buffer[ROWS-1][x].attr = 0x07; draw_char_at(' ', x, ROWS-1, 0x07); }
        cursor_y = ROWS - 1;
    }
}

void telemetry_update(int id, const char* s) {
    if (!global_fb) return;
    char buf[64]; int k=0; buf[k++]='['; buf[k++]='T'; buf[k++]=':'; buf[k++]='0'+(id%10); buf[k++]=']'; buf[k++]=' ';
    while(*s && k<60) buf[k++] = *s++; buf[k]=0;
    /* Drawing at ROWS is risky if ROWS*8*SCALE is exactly height. draw_char_at checks this now. */
    for (int i=0; i<k; i++) draw_char_at(buf[i], i, ROWS - 1, 0x0A); // Shifted to ROWS-1 for safety or use draw_char_at's check
}

void draw_pixel(int x, int y, uint32_t c) { if(global_fb && x>=0 && (uint64_t)x<global_fb->width && y>=0 && (uint64_t)y<global_fb->height) ((uint32_t*)global_fb->address)[(y*global_fb->pitch/4)+x]=c; }
void vga_set_cursor(int x, int y) { cursor_x=x; cursor_y=y; }
void vga_pulse_cursor(void) {}

struct limine_framebuffer_response* get_framebuffer(void);
void vga_serial_service(kernel_event_t event) {
    if (event == EVENT_INIT) {
        serial_init();
        struct limine_framebuffer_response* resp = get_framebuffer();
        if (resp && resp->framebuffer_count > 0) global_fb = resp->framebuffers[0];
        vga_clear();
    }
}
